SET XACT_ABORT ON;\nBEGIN TRANSACTION;\nIF COL_LENGTH('dbo.AccountScoreAward', 'AccessToken') IS NOT NULL\nBEGIN\n    ALTER TABLE dbo.AccountScoreAward ADD AccountId NVARCHAR(100) NULL;\n    EXEC(N'\n        IF EXISTS (\n            SELECT 1 FROM dbo.AccountScoreAward AS award\n            WHERE (SELECT COUNT(*) FROM dbo.Account AS account\n                   WHERE account.AccessToken = award.AccessToken) <> 1)\n            THROW 50001, ''Resolve historical award ownership before applying migration 002.'', 1;\n        UPDATE award SET AccountId = account.Id\n        FROM dbo.AccountScoreAward AS award\n        JOIN dbo.Account AS account ON account.AccessToken = award.AccessToken;\n        ALTER TABLE dbo.AccountScoreAward ALTER COLUMN AccountId NVARCHAR(100) NOT NULL;\n        ALTER TABLE dbo.AccountScoreAward DROP COLUMN AccessToken;\n    ');\nEND;\nCOMMIT;\n
